type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // We assume `shape.len() == 2` and both dimensions are positive.
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // If the length of `a` matches the number of rows, broadcast as a column vector.
    if a.len() == r {
        let mut mat: Matrix<i8> = Vec::with_capacity(r);
        for &elem in &a {
            // Repeat each element `c` times to form a full row.
            mat.push(vec![elem; c]);
        }
        mat
    }
    // Otherwise, it must match the number of columns; broadcast as a row vector.
    else {
        assert!(
            a.len() == c,
            "Length of input must match either the number of rows or columns"
        );
        let mut mat: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            // Clone the entire row vector for each row.
            mat.push(a.clone());
        }
        mat
    }
}

